const body = $input.first().json.body;
const count = parseInt(body.count);
const languages = body.languages;
const gameId = body.gameId;

return Array.from({ length: count }, (_, i) => ({
  json: {
    gameId: gameId,
    sentenceIndex: i + 1,
    totalCount: count,
    languages: languages
  }
}));

