const raw = $input.first().json.output.trim();

// Strip markdown fences if the model adds them anyway
const clean = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();

const parsed = JSON.parse(clean);

// Flatten translations into top-level fields for easy downstream access
const flatItem = {
  gameId: $input.first().json.gameId,
  sentenceIndex: parsed.sentenceIndex,
  ...parsed.translations
};

return [{ json: flatItem }];

// Collect all items accumulated by the loop
const allItems = $input.all();

// Sort by sentenceIndex to guarantee correct order
const sorted = allItems
  .map(item => item.json)
  .sort((a, b) => a.sentenceIndex - b.sentenceIndex);

// Grab gameId from first item (same for all)
const gameId = sorted[0].gameId;

// Detect language keys dynamically (everything except sentenceIndex and gameId)
const languages = Object.keys(sorted[0]).filter(k => k !== 'sentenceIndex' && k !== 'gameId');

// Build clean final structure
const sentences = sorted.map(item => ({
  id: item.sentenceIndex,
  translations: Object.fromEntries(
    languages.map(lang => [lang, item[lang]])
  )
}));

return [{
  json: {
    gameId: gameId,
    count: sentences.length,
    languages: languages,
    sentences: sentences
  }
}];
